unt":0,"campaign_expense_limit":6083000},{"id":"41bdb8ee-0dc9-4d01-a081-bef1d164630b","election_id":"6d807b31-ddb1-4ff4-9786-fc1388d298ae","region_id":"e645ba6f-4f0a-43c7-b56f-7420e87d5125","race_type":"city_councilor","title":"新竹市第7選舉區山地原住民議員選舉","voting_date":"2026-11-28","status":"announced","source_name":"中央選舉委員會公告：115年地方公職人員選舉","source_url":"https://gazette.nat.gov.tw/egFront/eguploadpubWrapper?file=%2FEG_FileManager%2Feguploadpub%2Feg032154%2Fch02%2Ftype3%2Fgov15%2Fnum2%2FEg.htm&metaid=167808","is_public":true,"created_at":"2026-08-22T21:25:35.862697+00:00","updated_at":"2026-08-23T17:02:20.109+00:00","external_id":"planned-2026-local-official-10018-07","district_scope":"新竹市之山地原住民","seat_count":1,"reserved_women_seat_count":0,"campaign_expense_limit":6063000}]$race_release$::jsonb) AS row(id uuid, election_id uuid, region_id uuid, race_type text, title text, voting_date date, status text, source_name text, source_url text, is_public boolean, created_at timestamptz, updated_at timestamptz, external_id text, district_scope text, seat_count integer, reserved_women_seat_count integer, campaign_expense_limit bigint);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM _party_release_prerequisite_races) <> 41
       OR EXISTS (SELECT 1 FROM _party_release_prerequisite_races WHERE is_public IS DISTINCT FROM TRUE OR voting_date <> DATE '2026-11-28') THEN
        RAISE EXCEPTION 'Reviewed 2026 grassroots prerequisite race payload drift';
    END IF;

    IF EXISTS (SELECT 1 FROM races existing JOIN _party_release_prerequisite_races incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM races existing JOIN _party_release_prerequisite_races incoming ON existing.external_id = incoming.external_id WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed 2026 grassroots prerequisite race identifier conflict';
    END IF;

    IF EXISTS (SELECT 1 FROM _party_release_prerequisite_races incoming LEFT JOIN elections election ON election.id = incoming.election_id WHERE election.id IS NULL)
       OR EXISTS (SELECT 1 FROM _party_release_prerequisite_races incoming LEFT JOIN regions region ON region.id = incoming.region_id WHERE region.id IS NULL) THEN
        RAISE EXCEPTION 'Reviewed 2026 grassroots prerequisite race parent data is missing';
    END IF;
END
$$;

INSERT INTO races (id, election_id, region_id, race_type, title, voting_date, status, source_name, source_url, is_public, created_at, updated_at, external_id, district_scope, seat_count, reserved_women_seat_count, campaign_expense_limit)
SELECT id, election_id, region_id, race_type, title, voting_date, status, source_name, source_url, is_public, created_at, updated_at, external_id, district_scope, seat_count, reserved_women_seat_count, campaign_expense_limit
FROM _party_release_prerequisite_races
ON CONFLICT (id) DO NOTHING;

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM races race JOIN _party_release_prerequisite_races release ON release.id = race.id WHERE race.is_public = TRUE) <> 41 THEN
        RAISE EXCEPTION 'Reviewed 2026 grassroots prerequisite race verification failed';
    END IF;
END
$$;

COMMIT;
